{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.LOGIC_FINAL_ITEM_MASTER AS WITH RankedData AS ( SELECT usercode, COMP_NAME AS BRAND, usercode AS EAN, CASE WHEN addlitemcode like \'MP%\' then addlitemcode WHEN ADDLITEMCODE like \'4C%\' then ADDLITEMCODE WHEN UPPER(ADDLITEMCODE) LIKE \'%T-SHIRT%\' OR UPPER(ADDLITEMCODE) LIKE \'%CO-ORDS%\' THEN replace(replace(UPPER(ADDLITEMCODE),\'T-SHIRT-\',\'\'),\'CO-ORDS-\',\'\') WHEN REGEXP_COUNT(ADDLITEMCODE, \'-\') = 3 THEN SPLIT_PART(ADDLITEMCODE, \'-\', 1)||\'-\'|| SPLIT_PART(ADDLITEMCODE, \'-\', 2)||\'-\'||SPLIT_PART(ADDLITEMCODE, \'-\', 4) ELSE ADDLITEMCODE END AS SKU, ITEMNAMEWOSHADE AS SKU_MAPPING, SHADE_NAME AS COLOR, PACKNAME AS SIZE, ITEMNAMEWITHSHADE AS STYLE, purrate::integer AS BASE_PRICE, basicrate::integer AS COST_PRICE, MRP::integer AS MRP, PACKING AS UNIT, ITEM_DESCRIPTION AS SKU_GROUP, GROUP_NAME1 AS CATEGORY, GROUP_NAME2 AS PRODUCT_TYPE, GROUP_NAME3 AS GENDER, GROUP_NAME4 AS FIT, GROUP_NAME5 AS VENDOR, GROUP_NAME12 AS SLEEVE, GROUP_NAME16 AS CLOSURE, GROUP_NAME17 AS \"PATTERN\", GROUP_NAME18 AS COLLAR, GROUP_NAME19 AS POCKET, GROUP_NAME22 AS RISE, REMARKS_1 as GARMENT_WEIGHT, ITEM_DESCRIPTION AS DESCRIPTION, ITEM_DESCRIPTION_3 as FABRIC_WEIGHT, ITEM_DESCRIPTION_2 AS COMPOSITION, GROUP_NAME23 AS \"ORIGIN_COUNTRY\", HSN_CODE AS HSN_CODE, GROUP_NAME25 AS HSNGROUP, GROUP_NAME30 AS GSTTYPE, TO_DATE(nullif(MODIFYDATE,\'\'),\'DD/MM/YYYY\') AS UPDATEDDATE, TO_DATE(nullif(CREATEDATE,\'\'),\'DD/MM/YYYY\') AS CREATEDDATE, GROUP_SHORT_NAME1 AS SKUTYPE, FLAG, GROUP_NAME11 AS DIM1, GROUP_NAME12 AS DIM2, GROUP_NAME13 AS DIM3, GROUP_NAME30 AS GST, RAW_OR_FINISH AS FINISHTYPE, ADDL_ITEM_NAME AS ITEMNAME, DAYS_TO_EXPIRE AS EXPIRY, ITEMDETAILCODE AS ITEMCODE, COMP_SHORT_NAME AS BRANDNAME, RO_LEVEL, MAX_LEVEL, MIN_LEVEL, INACTIVE_FOR_PO, INACTIVE_FOR_PR, INACTIVE_FOR_PU, INACTIVE_FOR_SL, INACTIVE_FOR_SO, INACTIVE_FOR_SR, ROW_NUMBER() OVER (PARTITION BY usercode ORDER BY _AIRBYTE_EMITTED_AT DESC) AS rn FROM snitch_db.maplemonk.LogicERPNew_get_item_master ) SELECT * FROM RankedData WHERE rn = 1; create or replace table snitch_db.maplemonk.ean_to_sku_mapping as select ean, sku from SNITCH_DB.MAPLEMONK.LOGIC_FINAL_ITEM_MASTER ; CREATE OR REPLACE TABLE snitch_db.maplemonk.logic_purchase_voucher AS WITH purchase_data AS ( SELECT \'PURCHASE_VOUCHER\' AS TYPE, CASE WHEN account_name in (\'SNITCH - WH - GUJARAT -SURAT\',\'SNITCH - WH - U.P -LUCKNOW\',\'SNITCH - WH - RAJASTHAN -JAIPUR\',\'SNITCH - WH - MADHYA PRADESH -INDORE\') AND branch_name LIKE \'%SNITCH%\' THEN \'VIRTUAL-STORE\' WHEN branch_name LIKE \'%SNITCH - WH%\' AND account_name LIKE \'%SNITCH%\' THEN \'STORE-WH\' WHEN branch_name LIKE \'%SNITCH - WH%\' THEN \'VENDOR-WH\' WHEN (branch_name LIKE \'%COCO%\' OR branch_name LIKE \'%FOCO%\' OR branch_name LIKE \'%COFO%\' OR branch_name LIKE \'%JAYAN%\' OR branch_name LIKE \'%BRIG%\') AND account_name LIKE \'%SNITCH - WH -%\' THEN \'WH-STORE\' ELSE \'OTHERS\' END AS ORIGIN, branch_name, account_name, BILL_NO, GRN_NUMBER, DOC_TYPE, QUANTITY, VOUCH_NO, to_date(BILL_DATE,\'DD/MM/YYYY\') as bill_date, TOTAL_TAX, AGENT_NAME, GRN_PREFIX, NET_AMOUNT, VOUCH_CODE, to_date(VOUCH_DATE,\'DD/MM/YYYY\') as vouch_date, ACTION_CODE, BRANCH_CODE, ACCOUNT_CODE, GROSS_AMOUNT, CURRENCY_NAME, DOC_TYPE_DESC, TAX_REGION_NAME, LISTITEMS from snitch_db.maplemonk.LOGICERPNEW_GET_PURCHASE_VOUCHER ), flattened_data AS ( SELECT pd.TYPE, pd.ORIGIN, pd.BILL_NO, pd.GRN_NUMBER, pd.DOC_TYPE, pd.QUANTITY, pd.VOUCH_NO, pd.BILL_DATE, pd.TOTAL_TAX, pd.AGENT_NAME, pd.GRN_PREFIX, pd.NET_AMOUNT, pd.VOUCH_CODE, pd.VOUCH_DATE, pd.ACTION_CODE, pd.BRANCH_CODE, pd.BRANCH_NAME as to_party, pd.ACCOUNT_CODE, pd.ACCOUNT_NAME as from_party, pd.GROSS_AMOUNT, pd.CURRENCY_NAME, pd.DOC_TYPE_DESC, pd.TAX_REGION_NAME, CASE WHEN UPPER( item.value:\"AddlItemCode\"::STRING) LIKE \'%T-SHIRT%\' OR UPPER( item.value:\"AddlItemCode\"::STRING) LIKE \'%CO-ORDS%\' THEN REGEXP_REPLACE( item.value:\"AddlItemCode\"::STRING, \'^([^-]+-[^-]+)-[^-]+-[^-]+-\', \'\\1-\') WHEN REGEXP_COUNT( item.value:\"AddlItemCode\"::STRING, \'-\') = 3 THEN REGEXP_REPLACE( item.value:\"AddlItemCode\"::STRING, \'^([^-]+-[^-]+)-[^-]+-\', \'\\1-\') ELSE item.value:\"AddlItemCode\"::STRING END AS SKU, item.value:\"CD\"::NUMBER AS CD, item.value:\"CD_Per\"::NUMBER AS CD_Per, item.value:\"CF_1\"::NUMBER AS CF_1, item.value:\"CF_2\"::NUMBER AS CF_2, item.value:\"CF_3\"::NUMBER AS CF_3, item.value:\"Gross_Pur_Amt\"::NUMBER AS Gross_Pur_Amt, item.value:\"HSN_Code\"::STRING AS HSN_Code, item.value:\"ItemCode\"::STRING AS ItemCode, item.value:\"Item_MRP\"::NUMBER AS Item_MRP, item.value:\"Item_Pur_Rate\"::NUMBER AS Item_Pur_Rate, item.value:\"Item_Sale_Rate\"::NUMBER AS Item_Sale_Rate, item.value:\"Item_Sp_Rate_1\"::NUMBER AS Item_Sp_Rate_1, item.value:\"Item_Sp_Rate_2\"::NUMBER AS Item_Sp_Rate_2, item.value:\"Item_Sp_Rate_3\"::NUMBER AS Item_Sp_Rate_3, item.value:\"Item_Sp_Rate_4\"::NUMBER AS Item_Sp_Rate_4, item.value:\"Item_Sp_Rate_5\"::NUMBER AS Item_Sp_Rate_5, item.value:\"Lot_Code\"::NUMBER AS Lot_Code, item.value:\"Lot_MRP\"::NUMBER AS Lot_MRP, item.value:\"Lot_Number\"::STRING AS Lot_Number, item.value:\"PackName\"::STRING AS PackName, item.value:\"Pur_Gross_Amt\"::NUMBER AS Pur_Gross_Amt, item.value:\"Pur_MRP\"::NUMBER AS Pur_MRP, item.value:\"Pur_Net_Amt\"::NUMBER AS Pur_Net_Amt, item.value:\"Pur_Net_Rate\"::NUMBER AS Pur_Net_Rate, item.value:\"Pur_Round_Amt\"::NUMBER AS Pur_Round_Amt, item.value:\"Pur_Txn_Code\"::NUMBER AS Pur_Txn_Code, item.value:\"Quantity\"::NUMBER AS Item_Quantity, item.value:\"Rate\"::NUMBER AS Rate, item.value:\"SP_CD\"::NUMBER AS SP_CD, item.value:\"SP_CD_Per\"::NUMBER AS SP_CD_Per, item.value:\"Scheme_Rs\"::NUMBER AS Scheme_Rs, item.value:\"Scheme_Unit\"::NUMBER AS Scheme_Unit, item.value:\"TD\"::NUMBER AS TD, item.value:\"TD_Per\"::NUMBER AS TD_Per, item.value:\"Tax_Amt_1\"::NUMBER AS Tax_Amt_1, item.value:\"Tax_Amt_3\"::NUMBER AS Tax_Amt_3 FROM purchase_data AS pd, LATERAL FLATTEN(input => pd.LISTITEMS) AS item ) SELECT distinct concat(bill_no,sku) as uniquekey ,* FROM flattened_data;",
                    "transaction": true
                }
            ) }}
